/* HITHER-LANDS:ally-seek-fn BEGIN */
/*
 * Active-ally faction behaviour (Hither Lands).
 *
 * A player-race monster that is well-disposed to the player is recorded as
 * neutral (target.midx == 0) and otherwise just stands idle.  Here it instead
 * seeks out the player's enemies: each turn, while still neutral, it acquires
 * the nearest monster that is itself hostile to the player (target.midx == -1)
 * and within its hearing range, then targets it so the existing
 * monster-vs-monster movement and combat paths take over.  When that enemy
 * dies, update_mon() resets our target to 0, so we reacquire next turn.
 *
 * This never sets target.midx to -1, so an ally never turns on the player;
 * provocation (being attacked or robbed) is handled elsewhere and still flips
 * the monster hostile as before.  Pure engine logic, no UI or savefile change.
 */
static void hl_ally_seek_enemy(struct monster *mon)
{
	int i, best = 0, best_dis = 0;

	/* Only player-race monsters can be allies, and only while neutral. */
	if (!mon->player_race || mon->target.midx != 0) return;

	for (i = 1; i < cave_monster_max(cave); i++) {
		struct monster *foe = cave_monster(cave, i);
		int dis;

		if (foe == mon || !foe->race) continue;

		/* Only fight monsters that are hostile to the player. */
		if (foe->target.midx != -1) continue;

		dis = distance(mon->grid, foe->grid);
		if (dis > mon->race->hearing) continue;

		if (!best || dis < best_dis) {
			best = i;
			best_dis = dis;
		}
	}

	if (best) {
		mon->target.midx = best;
		monster_make_heatmaps(cave, cave_monster(cave, best));
	}
}
/* HITHER-LANDS:ally-seek-fn END */

