/* HITHER-LANDS:recruit-fn BEGIN */
/*
 * Recruit / parley with an adjacent monster (Hither Lands, Phase 1).
 *
 * Walk up to a well-disposed player-race monster and try to persuade it to
 * follow you.  Eligibility: a neutral (target.midx == 0) monster of a playable
 * race, not already a follower, with you under your follower cap (1 + lev/15).
 * Persuasion uses the same save throw as the Command effect; a bad failure
 * gives offence and turns the monster hostile.  Aiming at an existing follower
 * releases it.
 */
static void do_cmd_recruit_aux(int dir)
{
	struct loc grid = loc_sum(player->grid, ddgrid[dir]);
	struct monster *mon = square_monster(cave, grid);
	char m_name[80];
	int i, followers = 0, cap;

	/* Need somebody to talk to */
	if (!mon) {
		msg("There is nobody there to parley with.");
		return;
	}

	monster_desc(m_name, sizeof(m_name), mon, MDESC_CAPITAL | MDESC_COMMA);

	/* Parleying takes a turn */
	player->upkeep->energy_use = z_info->move_energy;

	/* Dismiss an existing follower */
	if (mflag_has(mon->mflag, MFLAG_FOLLOWER)) {
		mflag_off(mon->mflag, MFLAG_FOLLOWER);
		msg("%s stops following you.", m_name);
		return;
	}

	/* Only well-disposed player-race folk will consider joining */
	if (!mon->player_race || (mon->target.midx != 0)) {
		msg("%s refuses to join you.", m_name);
		return;
	}

	/* Enforce the follower cap */
	cap = 1 + player->lev / 15;
	for (i = 1; i < cave_monster_max(cave); i++) {
		struct monster *m = cave_monster(cave, i);
		if (m->race && mflag_has(m->mflag, MFLAG_FOLLOWER)) followers++;
	}
	if (followers >= cap) {
		msg("You cannot lead any more followers.");
		return;
	}

	/* Persuasion roll (as for the Command effect) */
	if (randint1(player->lev) < randint1(mon->race->level)) {
		/* A heavy failure gives offence */
		if (mon->race->level > player->lev + 5) {
			mon->target.midx = -1;
			monster_wake(mon, false, 100);
			msg("%s takes offence and turns hostile!", m_name);
		} else {
			msg("%s is unconvinced.", m_name);
		}
		return;
	}

	/* Success */
	mflag_on(mon->mflag, MFLAG_FOLLOWER);
	monster_wake(mon, false, 100);
	msg("%s agrees to follow you.", m_name);
}

void do_cmd_recruit(struct command *cmd)
{
	int dir;

	if (cmd_get_direction(cmd, "direction", &dir, false) != CMD_OK)
		return;

	do_cmd_recruit_aux(dir);
}
/* HITHER-LANDS:recruit-fn END */

